const item = $input.first().json;
const headers = item.headers ?? {};
const provided = String(headers['x-n8n-secret'] ?? headers['X-N8N-Secret'] ?? '');
const expected = String($env.N8N_WEBHOOK_SECRET ?? '');
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured in n8n');
if (provided.length !== expected.length) throw new Error('Unauthorized: bad webhook secret');
let diff = 0;
for (let i = 0; i < expected.length; i++) diff |= provided.charCodeAt(i) ^ expected.charCodeAt(i);
if (diff !== 0) throw new Error('Unauthorized: bad webhook secret');
return [$input.first()];

const hasHf = Boolean($env.HF_TOKEN);
return [{ json: { llmAvailable: hasHf,
  engine: hasHf ? 'hf-inference (TODO wire)' : 'template-v1 (deterministic)',
  note: 'Template engine builds §7 scripts ONLY from verified facts — nothing invented.' } }];

const wh = $('webhook-entry').first().json;
const p = (wh.body ?? wh).product ?? {};
const facts = (p.facts ?? []).filter(f => f.claim && f.source);
const feat = facts.slice(0, 3).map(f => f.claim);
const name = p.name ?? 'yeh product';
// §7 structure: hook → intro → features → use case → explanation → CTA → caption/hashtags.
// Rules: no prices, no fake urgency, no guarantees, neutral CTA.
const script = {
  hook: `${name} — kya aapne iske baare mein suna hai?`,
  intro: `${name} ${p.category ?? ''} mein ek useful option hai.`.trim(),
  features: feat,
  useCase: p.useCase ?? 'Rozmarra ke istemal ke liye banaya gaya hai.',
  explanation: 'Neeche diye gaye link se aap iske baare mein aur jaan sakte hain.',
  cta: 'View Product', // neutral CTA only (§7); never 'buy now' pressure
  caption: `${name} ke baare mein jaankari. #reels #productfinds`,
  hashtags: ['#reels', '#productfinds', '#honestreview'],
};
return [{ json: { product: p, script, engine: 'template-v1 (deterministic)',
  llmAvailable: $input.first().json.llmAvailable } }];

const j = $input.first().json;
const text = JSON.stringify(j.script);
const violations = [];
if (/₹|Rs\.?\s*\d|\$\s*\d|\b\d+\s*%\s*off\b|\bdiscount\b|\boffer\b|\bfree\b/i.test(text))
  violations.push('price_or_discount_mention');
if (/limited\s*time|hurry|only\s+\d+\s+left|act\s+now|jaldi\s+karein/i.test(text))
  violations.push('fake_urgency');
if (/guaranteed|100%\s+(sure|result)|pakka\s+wada/i.test(text))
  violations.push('false_guarantee');
if (/best\s+in\s+the\s+world|number\s*one/i.test(text))
  violations.push('exaggerated_claim');
return [{ json: { ...j, violations, clean: violations.length === 0 } }];

const j = $input.first().json;
return [{ json: { product: { ...j.product, state: 'SCRIPTED',
  scriptedAt: new Date().toISOString() }, script: j.script } }];

console.log('[script] NEEDS_REVIEW', $json.violations);
return [{ json: { product: { ...$json.product, state: 'NEEDS_REVIEW' },
  violations: $json.violations } }];
